(()=>{'use strict';const trigger=document.querySelector('#deskSearch'),header=document.querySelector('main>header');if(!trigger||!header)return;const date=document.querySelector('#deskDate'),account=header.querySelector('.header-tools');if(date&&account){const keepDate=()=>{const person=account.querySelector('.shared-user');if(person){if(date.nextElementSibling!==person)account.insertBefore(date,person)}else if(account.firstElementChild!==date)account.prepend(date)};keepDate();new MutationObserver(keepDate).observe(account,{childList:true})}const box=document.createElement('div');box.id='headerSearchBox';box.className='header-search-box';box.hidden=false;box.innerHTML='<span aria-hidden="true">⌕</span><input type="search" id="headerTaskSearch" placeholder="جست‌وجوی کار، مسئول یا همکار…" aria-label="جست‌وجوی کارها" autocomplete="off"><button type="button" aria-label="بستن جست‌وجو">×</button>';header.append(box);const anchor=document.createComment('search-field');box.before(anchor);const modal=document.createElement('dialog');modal.className='header-search-modal';modal.setAttribute('aria-label','جست‌وجوی کارها');document.body.append(modal);modal.addEventListener('cancel',e=>{e.preventDefault();close()});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});const input=box.querySelector('input'),closeButton=box.querySelector('button');let timer;function target(){return document.querySelector('#personalSearch,#sharedSearch,#claritySearch')}function prepare(){if(target())return true;const personal=!!window.SAMANDIS_PERSONAL_MODE,nav=document.querySelector('[data-desk-view="'+(personal?'mine':'all')+'"]');nav?.click();return !!target()}function open(){if(header.classList.contains('header-search-open'))return;if(!prepare())return;input.value=target()?.value||'';box.hidden=false;modal.append(box);modal.showModal();document.documentElement.classList.add('search-modal-open');header.classList.add('header-search-open');trigger.setAttribute('aria-expanded','true');input.focus()}function close(reset=false){if(reset){input.value='';clearTimeout(timer);timer=null;apply()}clearTimeout(timer);if(timer){timer=null;apply()}box.hidden=false;modal.close();anchor.after(box);document.documentElement.classList.remove('search-modal-open');header.classList.remove('header-search-open');trigger.setAttribute('aria-expanded','false');input.blur();trigger.focus()}function apply(){const original=target();if(!original)return;const focused=document.activeElement===input,pos=input.selectionStart;original.value=input.value;original.dispatchEvent(new Event('input',{bubbles:true}));if(focused){input.focus();if(pos!==null&&input.type==='text')input.setSelectionRange(pos,pos)}}trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls',box.id);trigger.setAttribute('aria-expanded','false');trigger.onclick=open;input.addEventListener('focus',open);closeButton.onclick=()=>close(true);input.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{timer=null;apply()},160)};input.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close(true)}if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);timer=null;apply()}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();e.stopImmediatePropagation();open()}},true);document.addEventListener('pointerdown',e=>{if(header.classList.contains('header-search-open')&&!box.contains(e.target)&&!trigger.contains(e.target)){close()}});})();
